const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("owner cap: enforced on create", async () => {
  const { base, close } = startServer();
  try {
    for (let i = 0; i < 3; i++) {
      const resp = await api(base, "POST", "/api/links", {
        url: `https://example.com/${i}`,
        owner: "dev",
      });
      assert.strictEqual(resp.status, 201);
    }

    const overflow = await api(base, "POST", "/api/links", {
      url: "https://example.com/overflow",
      owner: "dev",
    });
    assert.strictEqual(overflow.status, 409);
  } finally {
    await close();
  }
});

test("owner cap: enforced on reassignment", async () => {
  const { base, close } = startServer();
  try {
    for (let i = 0; i < 3; i++) {
      await api(base, "POST", "/api/links", { url: `https://example.com/${i}`, owner: "dev" });
    }
    const free = await api(base, "POST", "/api/links", {
      url: "https://example.com/free",
      slug: "free-link",
    });
    assert.strictEqual(free.status, 201);

    const reassign = await api(base, "PATCH", "/api/links/free-link/owner", { owner: "dev" });
    assert.strictEqual(reassign.status, 409);
  } finally {
    await close();
  }
});

